Here's a sample code snippet in Python that demonstrates how to publish blog opinions, comments, and analyze them as a behavior using a simple console-based application:

**Blog Application Code**
```python
import datetime

class BlogPost:
    def __init__(self, title, content):
        self.title = title
        self.content = content
        self.comments = []

    def add_comment(self, comment):
        self.comments.append(comment)

class Comment:
    def __init__(self, author, content):
        self.author = author
        self.content = content
        self.date = datetime.datetime.now()

class BlogAnalyzer:
    def __init__(self):
        self.posts = []

    def add_post(self, post):
        self.posts.append(post)

    def analyze_posts(self):
        total_comments = 0
        positive_comments = 0
        negative_comments = 0

        for post in self.posts:
            total_comments += len(post.comments)
            for comment in post.comments:
                if comment.content.lower().find('positive')!= -1:
                    positive_comments += 1
                elif comment.content.lower().find('negative')!= -1:
                    negative_comments += 1

        print(f"Total Comments: {total_comments}")
        print(f"Positive Comments: {positive_comments}")
        print(f"Negative Comments: {negative_comments}")

def main():
    analyzer = BlogAnalyzer()

    while True:
        print("1. Add Blog Post")
        print("2. Add Comment to Post")
        print("3. Analyze Blog Posts")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            title = input("Enter blog post title: ")
            content = input("Enter blog post content: ")
            post = BlogPost(title, content)
            analyzer.add_post(post)
            print("Blog post added successfully!")
        elif choice == "2":
            post_title = input("Enter post title: ")
            for post in analyzer.posts:
                if post.title == post_title:
